Atomic rollback:
# One short participant blocks the entire batch.
currency HKD decimals 2;
account A HKD 5.00;
account B HKD 0.00;
account C HKD 0.00;
pay ab A -> B 6.00 HKD;
pay bc B -> C 6.00 HKD;
net insufficient { ab, bc };
assert total HKD 5.00;
